<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import type { Order } from './types'
const props = withDefaults(defineProps<{ orders: Order[]; busy: boolean; pageSize?: number }>(), { pageSize: 8 })
defineEmits<{ resume: [order: Order]; recheck: [order: Order] }>()
const page = ref(1), pages = computed(() => Math.max(1,Math.ceil(props.orders.length/props.pageSize)))
watch(pages, n => {page.value=Math.min(page.value,n)})
const rows = computed(() => props.orders.slice((page.value-1)*props.pageSize,page.value*props.pageSize))
const time = (s:string) => new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
const money = (n:number) => (n/100).toFixed(2)
const credit = (o:Order) => o.credited_credit ?? (o.status==='paid' ? o.credit : null)
const label = (o:Order) => o.reversed_at ? '已退款' : o.status==='paid' ? '已到账' : o.gateway_status==='expired' ? '已过期' : '待支付'
</script>
<template><div class="order-list"><div class="table-wrap"><table><thead><tr><th>订单 / 时间</th><th>应付 / 实付</th><th>到账 / 状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in rows" :key="o.id"><td><code :title="o.id">{{ o.id.slice(0,10) }}…{{ o.id.slice(-4) }}</code><small>{{ time(o.created_at) }} · {{ o.payment_type==='wxpay' ? '微信' : '支付宝' }}</small></td><td><strong>¥{{ money(o.amount_cents) }}</strong><small>{{ o.paid_amount_cents != null ? `实付 ¥${money(o.paid_amount_cents)}` : '尚未确认收款' }}</small></td><td><strong :class="{ green:o.status==='paid' && !o.reversed_at }">{{ credit(o) != null ? `$${Number(credit(o))}` : '—' }}</strong><small class="status" :class="{ green:o.status==='paid' && !o.reversed_at }">{{ label(o) }}</small></td><td><div v-if="o.status==='pending'" class="actions"><button v-if="o.gateway_status!=='expired'" :disabled="busy" @click="$emit('resume',o)">继续支付</button><button :disabled="busy" @click="$emit('recheck',o)">查到账</button></div><span v-else class="done">{{ o.reversed_at ? '已冲正' : '自动入账 ✓' }}</span></td></tr></tbody></table></div><p v-if="!orders.length" class="empty">暂无充值订单，选择上方套餐开始充值。</p><div class="pagination"><span>共 {{ orders.length }} 笔 · {{ page }} / {{ pages }} 页</span><div><button :disabled="page<=1" @click="page--">上一页</button><button :disabled="page>=pages" @click="page++">下一页</button></div></div></div></template>
<style scoped>
.order-list{color:#34435b;color-scheme:light}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;color:#34435b;font-size:11px}th{font-weight:500;color:#8b97a8;background:#fafbfe;padding:10px 14px;white-space:nowrap}td{color:#34435b;padding:10px 14px;border-bottom:1px solid #f0f2f7;line-height:1.5;vertical-align:middle}code{font-size:10px;color:#435774;white-space:nowrap}strong{font-weight:600;color:#364760;font-size:12px;white-space:nowrap}small{display:block;color:#8a97aa;font-size:10px;margin-top:3px;white-space:nowrap}.green{color:#239c68}.done{color:#8393a9;font-size:10px;white-space:nowrap}.actions{display:flex;gap:4px;flex-wrap:wrap}button{font-size:10px;color:#5273aa;background:#f1f5fc;border:1px solid #e2e9f4;padding:5px 7px;border-radius:5px;white-space:nowrap;cursor:pointer}button:disabled{opacity:.35;cursor:not-allowed}.pagination{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;font-size:10px;color:#92a0b3;gap:10px}.pagination>div{display:flex;gap:5px}.pagination button{color:#647896;background:white;padding:4px 8px}.empty{padding:25px 14px;text-align:center;font-size:12px;color:#8c9bb0;margin:0}@media(max-width:680px){td,th{padding:10px}.actions{flex-direction:column}code{font-size:9px}}
</style>
